create table veranolink.vl_users (
    vl_id_user    number generated by default as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache 20 noorder
    nocycle nokeep noscale not null enable,
    name          varchar2(100 char),
    email         varchar2(100 char),
    password      varchar2(1000 byte),
    vl_id_company number,
    created_date  date,
    vl_id_rol     number,
    state         number,
    token         clob,
    time_expired  timestamp(6),
    active        number
);

alter table veranolink.vl_users add primary key ( vl_id_user )
    using index enable;

